import { describe, it, expect } from 'vitest';
import {
  addTodo,
  toggleTodo,
  removeTodo,
  clearCompleted,
  filterTodos,
} from './todos.js';

const sample = [
  { id: 1, text: 'a', done: false },
  { id: 2, text: 'b', done: true },
];

describe('todo helpers', () => {
  it('adds a trimmed todo and ignores blank input', () => {
    const next = addTodo([], '  buy milk  ');
    expect(next).toHaveLength(1);
    expect(next[0].text).toBe('buy milk');
    expect(next[0].done).toBe(false);
    expect(addTodo(sample, '   ')).toBe(sample);
  });

  it('toggles done state for one id only', () => {
    const next = toggleTodo(sample, 1);
    expect(next[0].done).toBe(true);
    expect(next[1].done).toBe(true);
  });

  it('removes a todo by id', () => {
    expect(removeTodo(sample, 2)).toEqual([sample[0]]);
  });

  it('clears completed todos', () => {
    expect(clearCompleted(sample)).toEqual([sample[0]]);
  });

  it('filters by active / completed / all', () => {
    expect(filterTodos(sample, 'active')).toEqual([sample[0]]);
    expect(filterTodos(sample, 'completed')).toEqual([sample[1]]);
    expect(filterTodos(sample, 'all')).toEqual(sample);
  });
});
EOF
